import React, { useState } from "react";
import { User, Building, Mail, Phone } from "lucide-react";
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";

const styles = `
  .custom-bg {
    background: linear-gradient(135deg, #d9d9d9 0%, #f0f0f0 50%, #d9d9d9 100%);
    min-height: 100vh;
  }
  
  .custom-card {
    background: rgba(255, 255, 255, 0.95);
    border: 4px solid #003865;
    border-radius: 20px;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  }
  
  .custom-input {
    background-color: #d9d9d9;
    border: 2px solid #d9d9d9;
    border-radius: 12px;
    padding-left: 3rem;
    padding-right: 1rem;
    padding-top: 1rem;
    padding-bottom: 1rem;
    font-size: 1rem;
    transition: all 0.3s ease;
     max-width: 400px; /* Limiter la largeur */
  height: 48px; /* Hauteur plus standard */
  }
  
  .custom-input:focus {
    background-color: #d9d9d9;
    border-color: #003865;
    box-shadow: 0 0 0 0.2rem rgba(0, 56, 101, 0.25);
  }
  
  .custom-input.is-invalid {
    border-color: #dc3545;
  }
  
  .input-icon {
    position: absolute;
    left: 15px;
    top: 50%;
    transform: translateY(-50%);
    color: #003865;
    z-index: 10;
    pointer-events: none;
  }
  
  .custom-btn {
    background: linear-gradient(135deg, #003865 0%, #ef5b0c 100%);
    border: none;
    border-radius: 12px;
    font-weight: 600;
    padding: 12px 24px;
    transition: all 0.3s ease;
    color: red
  }
  
  .custom-btn:hover {
    transform: scale(1.05);
    box-shadow: 0 10px 25px rgba(0, 56, 101, 0.3);
  }
  
  .custom-btn:disabled {
    opacity: 0.5;
    transform: none;
  }
  
  .text-primary-custom {
    color: #003865 !important;
  }
  
  .text-orange-custom {
    color: #ef5b0c !important;
  }
  
  .text-orange-custom:hover {
    color: #d84e0a !important;
    text-decoration: underline;
  }
`;

const InputField = ({
  icon: Icon,
  type = "text",
  placeholder,
  value,
  onChange,
  error,
  id,
}) => (
  <div className="mb-3 position-relative">
    <div className="input-icon">
      <Icon size={20} />
    </div>
    <input
      type={type}
      className={`form-control custom-input ${error ? "is-invalid" : ""}`}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      id={id}
      style={{ paddingLeft: "3rem", height: "3.5rem" }}
    />
    {error && <div className="invalid-feedback">{error}</div>}
  </div>
);

export default function InscriptionBootstrap() {
  const [formData, setFormData] = useState({
    nomEntreprise: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    email: "",
    telephone: "",
  });
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (field) => (e) => {
    setFormData((prev) => ({ ...prev, [field]: e.target.value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: "" }));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.nomEntreprise.trim())
      newErrors.nomEntreprise = "Le nom de l'entreprise est requis";
    if (!formData.nomRepresentant.trim())
      newErrors.nomRepresentant = "Le nom du représentant est requis";
    if (!formData.prenomRepresentant.trim())
      newErrors.prenomRepresentant = "Le prénom du représentant est requis";

    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Format d'email invalide";
    }

    if (!formData.telephone.trim()) {
      newErrors.telephone = "Le numéro de téléphone est requis";
    } else if (!/^[0-9+\-\s()]+$/.test(formData.telephone)) {
      newErrors.telephone = "Format de téléphone invalide";
    }

    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validateForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      alert("Inscription réussie !");
    }, 2000);
  };

  return (
    <>
      <div className="text-start mb-3">
        <a href="/" className="text-orange-custom small text-decoration-none">
          ← Accueil
        </a>
      </div>
      <style>{styles}</style>
      <link
        href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.0/css/bootstrap.min.css"
        rel="stylesheet"
      />

      <div className=" d-flex align-items-center justify-content-center p-5">
        <div className="container">
          <div className="row justify-content-center">
            <div className="col-12 col-md-11 col-lg-10 col-xl-9">
              <div className="custom-card p-4 p-sm-5">
                <div className="text-center mb-4">
                  <h2 className="h2 fw-bold text-primary-custom mb-2">
                    Inscription Entreprise
                  </h2>
                  <p className="text-primary-custom opacity-75">
                    Rejoignez notre plateforme dès aujourd'hui
                  </p>
                </div>

                <div>
                  <InputField
                    icon={Building}
                    placeholder="Nom de l'entreprise"
                    value={formData.nomEntreprise}
                    onChange={handleChange("nomEntreprise")}
                    error={errors.nomEntreprise}
                    id="nomEntreprise"
                  />

                  <div className="row">
                    <div className="col-12 col-sm-6">
                      <InputField
                        icon={User}
                        placeholder="Nom du représentant"
                        value={formData.nomRepresentant}
                        onChange={handleChange("nomRepresentant")}
                        error={errors.nomRepresentant}
                        id="nomRepresentant"
                      />
                    </div>
                    <div className="col-12 col-sm-6">
                      <InputField
                        icon={User}
                        placeholder="Prénom du représentant"
                        value={formData.prenomRepresentant}
                        onChange={handleChange("prenomRepresentant")}
                        error={errors.prenomRepresentant}
                        id="prenomRepresentant"
                      />
                    </div>
                  </div>

                  <InputField
                    icon={Mail}
                    type="email"
                    placeholder="Adresse email"
                    value={formData.email}
                    onChange={handleChange("email")}
                    error={errors.email}
                    id="email"
                  />

                  <InputField
                    icon={Phone}
                    type="tel"
                    placeholder="Numéro de téléphone"
                    value={formData.telephone}
                    onChange={handleChange("telephone")}
                    error={errors.telephone}
                    id="telephone"
                  />

                  <div className="pt-3">
                    <button
                      type="button"
                      className="btn custom-btn text-white w-100"
                      disabled={isLoading}
                      onClick={handleSubmit}
                    >
                      {isLoading
                        ? "Inscription en cours..."
                        : "Créer le compte entreprise"}
                    </button>
                  </div>
                </div>

                <div className="text-center mt-4">
                  <p className="small text-primary-custom">
                    Déjà un compte ?{" "}
                    <a
                      href="/connexion"
                      className="text-orange-custom text-decoration-none fw-medium"
                    >
                      Se connecter
                    </a>
                  </p>
                </div>

                <div className="text-center mt-3">
                  <p className="small text-primary-custom opacity-75">
                    En vous inscrivant, vous acceptez nos{" "}
                    <a
                      href="#"
                      className="text-orange-custom text-decoration-none"
                    >
                      conditions d'utilisation
                    </a>{" "}
                    et notre{" "}
                    <a
                      href="#"
                      className="text-orange-custom text-decoration-none"
                    >
                      politique de confidentialité
                    </a>
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
